import{_ as e,o as r,c as a,a3 as n}from"./chunks/framework.DxEvSMU4.js";const g=JSON.parse('{"title":"授權速查","description":"","frontmatter":{},"headers":[],"relativePath":"ref/licenses.md","filePath":"ref/licenses.md","lastUpdated":1793029011000}'),d={name:"ref/licenses.md"};function i(o,t,l,s,c,h){return r(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="授權速查" tabindex="-1">授權速查 <a class="header-anchor" href="#授權速查" aria-label="Permalink to &quot;授權速查&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">使用前請先看</p><p>授權條款會改版 (Dify, MinerU, LobeHub 都曾改過, 改版紀錄來源待補), 以下為 2026-10-26 研究整理, 對外提供服務前請以各專案儲存庫的授權檔為準. 個人與內部使用通常不受影響 (信心: 中). 本頁不構成法律意見, 如有疑義請洽法律顧問.</p></div><h2 id="osi-開源與「原始碼公開」" tabindex="-1">OSI 開源與「原始碼公開」 <a class="header-anchor" href="#osi-開源與「原始碼公開」" aria-label="Permalink to &quot;OSI 開源與「原始碼公開」&quot;">​</a></h2><p>授權是作者對使用方式訂下的規則. 「開源」在業界有明確的定義, 看得到原始碼不等於開源.</p><p>OSI (Open Source Initiative) 定義的開源授權不得對使用方式設限. 授權對使用方式有限制者, 原始碼雖然公開, 但不屬於 OSI 開源. 以 n8n 為例, 其授權檔 (Sustainable Use License) 規定軟體只能用於自身內部業務或非商業用途, 與 OSI 開源定義第 6 條 (授權不得限制特定使用領域) 不符. n8n 官方文件亦自述 &quot;according to the Open Source Initiative (OSI), open source licenses can&#39;t include limitations on use, so we do not call ourselves open source&quot; (此句引自先前整理, docs.n8n.io 原頁本輪未能擷取, 來源待補).</p><p>本手冊對這類專案稱「原始碼公開」, 不稱「開源」.</p><h2 id="軟體授權" tabindex="-1">軟體授權 <a class="header-anchor" href="#軟體授權" aria-label="Permalink to &quot;軟體授權&quot;">​</a></h2><table tabindex="0"><thead><tr><th>專案</th><th>授權</th><th>OSI 開源</th><th>對外提供服務時的重點</th></tr></thead><tbody><tr><td>Open WebUI</td><td>Open WebUI License (BSD-3 條款加品牌條款)</td><td>否</td><td>品牌條款禁止修改或移除 &quot;Open WebUI&quot; 標示; 例外為任意連續 30 日內終端使用者不超過 50 人, 或取得書面許可或企業授權</td></tr><tr><td>LibreChat</td><td>MIT (管理面板為 AGPL)</td><td>是</td><td>管理面板為獨立儲存庫, 授權檔為 AGPL-3.0, 須另行留意</td></tr><tr><td>AnythingLLM</td><td>MIT</td><td>是</td><td>-</td></tr><tr><td>LobeHub (原 LobeChat)</td><td>LobeHub Community License</td><td>否</td><td>散布修改後的衍生作品須商業授權, 不適合手冊建議改作</td></tr><tr><td>LiteLLM</td><td>MIT, <code>enterprise/</code> 目錄另有授權</td><td>部分</td><td><code>enterprise/</code> 目錄的程式碼於正式環境使用須簽訂 BerriAI 企業條款; 「SSO 等功能屬企業版」的說法來源待補</td></tr><tr><td>LangGraph 程式庫</td><td>MIT</td><td>是</td><td>自行部署官方 Agent Server 須提供授權金鑰 (LANGGRAPH_CLOUD_LICENSE_KEY)</td></tr><tr><td>Langflow</td><td>MIT</td><td>是</td><td>-</td></tr><tr><td>n8n</td><td>Sustainable Use License 與 Enterprise License</td><td>否</td><td>限自身內部業務或非商業用途; 檔名含 <code>.ee.</code> 的原始碼須企業授權; 官方自述非開源</td></tr><tr><td>Flowise</td><td>Apache 2.0 (<code>packages/server/src/enterprise</code> 目錄為商業授權)</td><td>部分</td><td>企業目錄的程式碼須商業授權</td></tr><tr><td>Dify</td><td>Dify Open Source License (以 Apache 2.0 修改)</td><td>否</td><td>未經書面授權不得營運多租戶服務 (一個 workspace 為一個租戶); 使用前端 (<code>web/</code>) 時不得移除標誌與版權資訊</td></tr><tr><td>MinerU</td><td>MinerU Open Source License (Apache 2.0 加附加條款; 「3.1.0 起」的版本界線來源待補)</td><td>否</td><td>月活躍使用者超過 1 億或月營收超過 2,000 萬美元須另取商業授權; 線上服務須標示</td></tr><tr><td>Docling</td><td>MIT</td><td>是</td><td>-</td></tr><tr><td>Qdrant</td><td>Apache 2.0</td><td>是</td><td>-</td></tr><tr><td>Arize Phoenix</td><td>Elastic License 2.0</td><td>否</td><td>不得將軟體作為託管或管理服務提供給第三方</td></tr><tr><td>promptfoo</td><td>MIT</td><td>是</td><td>所有權已變動, 見版本頁</td></tr><tr><td>Langfuse</td><td>MIT (<code>ee/</code> 等目錄另有授權)</td><td>部分</td><td><code>ee/</code> 目錄的程式碼不在 MIT 範圍</td></tr><tr><td>llama-swap</td><td>MIT</td><td>是</td><td>-</td></tr><tr><td>pgvector</td><td>PostgreSQL License</td><td>是</td><td>-</td></tr><tr><td>sqlite-vec</td><td>MIT 與 Apache 2.0 雙授權</td><td>是</td><td>儲存庫同時附兩份授權檔</td></tr></tbody></table><h2 id="模型授權" tabindex="-1">模型授權 <a class="header-anchor" href="#模型授權" aria-label="Permalink to &quot;模型授權&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模型</th><th>授權</th><th>備註</th></tr></thead><tbody><tr><td>Llama 系列 (含 Prompt Guard 2, Llama Guard 4)</td><td>Llama 4 Community License</td><td>Hugging Face 上須登入並填表取得存取權. 授權要點: 前一曆月月活躍使用者逾 7 億須向 Meta 申請授權; 須顯示 &quot;Built with Llama&quot;; 須遵守 Acceptable Use Policy</td></tr><tr><td>Snowflake Arctic Embed L v2.0</td><td>Apache 2.0</td><td>Snowflake 發布, 約 5.7 億參數, 模型卡標示可免費商用</td></tr><tr><td>EmbeddingGemma</td><td>Gemma Terms of Use</td><td>Google 發布, 約 3 億參數; 須接受條款才能下載. 條款要點: 散布時須轉遞使用限制並附條款全文; Google 不主張對輸出內容的權利</td></tr><tr><td>Gemma-3-TAIDE-12b-Chat-2602</td><td>(Gemma 版次)-TAIDE 模型授權條款</td><td>基底為 google/gemma-3-12b-pt; 須接受條款才能下載; 條款全文在外部連結, 商用條件本輪未擷取, 來源待補</td></tr><tr><td>llama-nemotron-rerank-1b-v2</td><td>OpenMDW-1.1, 另附 Llama 3.2 Community License</td><td>NVIDIA 發布的重排序模型, 以 Llama-3.2-1B 微調; 模型卡標示可商用. Llama 3.2 授權條款本輪未擷取, 對外提供服務前請讀全文</td></tr><tr><td>mmarco-mMiniLMv2-L12-H384-v1</td><td>Apache 2.0</td><td>cross-encoder 發布的多語言重排序模型, 以機器翻譯的 MS MARCO 訓練</td></tr></tbody></table><p>其餘模型授權見 <a href="/lanai-handbook/know/k4-licenses">K4</a>.</p><h2 id="授權疊加" tabindex="-1">授權疊加 <a class="header-anchor" href="#授權疊加" aria-label="Permalink to &quot;授權疊加&quot;">​</a></h2><p>組合多個元件後再對外提供服務時, 最嚴格的條款決定能做什麼 (信心: 中). 原始碼公開但非 OSI 開源的元件清單: Open WebUI, Dify, LobeHub, MinerU, Arize Phoenix, n8n; 模型端另有 Llama 4 Community License.</p><h2 id="參考來源" tabindex="-1">參考來源 <a class="header-anchor" href="#參考來源" aria-label="Permalink to &quot;參考來源&quot;">​</a></h2><p>授權條款全文與官方頁面 (2026-10-26 擷取):</p><ul><li><a href="https://opensource.org/osd" target="_blank" rel="noreferrer">Open Source Definition, OSI</a></li><li><a href="https://raw.githubusercontent.com/open-webui/open-webui/main/LICENSE" target="_blank" rel="noreferrer">Open WebUI 授權檔</a></li><li><a href="https://raw.githubusercontent.com/danny-avila/LibreChat/main/LICENSE" target="_blank" rel="noreferrer">LibreChat 授權檔</a>, <a href="https://raw.githubusercontent.com/ClickHouse/librechat-admin-panel/main/LICENSE" target="_blank" rel="noreferrer">LibreChat 管理面板授權檔</a>, <a href="https://www.librechat.ai/docs/features/admin_panel" target="_blank" rel="noreferrer">LibreChat 管理面板文件</a></li><li><a href="https://raw.githubusercontent.com/Mintplex-Labs/anything-llm/master/LICENSE" target="_blank" rel="noreferrer">AnythingLLM 授權檔</a></li><li><a href="https://raw.githubusercontent.com/lobehub/lobe-chat/main/LICENSE" target="_blank" rel="noreferrer">LobeHub Community License</a></li><li><a href="https://raw.githubusercontent.com/BerriAI/litellm/main/LICENSE" target="_blank" rel="noreferrer">LiteLLM 授權檔</a>, <a href="https://raw.githubusercontent.com/BerriAI/litellm/main/enterprise/LICENSE.md" target="_blank" rel="noreferrer">LiteLLM enterprise 授權檔</a></li><li><a href="https://raw.githubusercontent.com/langchain-ai/langgraph/main/LICENSE" target="_blank" rel="noreferrer">LangGraph 授權檔</a>, <a href="https://docs.langchain.com/langsmith/deploy-standalone-server" target="_blank" rel="noreferrer">LangChain 文件: 自行部署 standalone server</a></li><li><a href="https://raw.githubusercontent.com/langflow-ai/langflow/main/LICENSE" target="_blank" rel="noreferrer">Langflow 授權檔</a></li><li><a href="https://raw.githubusercontent.com/n8n-io/n8n/master/LICENSE.md" target="_blank" rel="noreferrer">n8n 授權檔</a></li><li><a href="https://raw.githubusercontent.com/FlowiseAI/Flowise/main/LICENSE.md" target="_blank" rel="noreferrer">Flowise 授權檔</a></li><li><a href="https://raw.githubusercontent.com/langgenius/dify/main/LICENSE" target="_blank" rel="noreferrer">Dify 授權檔</a></li><li><a href="https://raw.githubusercontent.com/opendatalab/MinerU/master/LICENSE.md" target="_blank" rel="noreferrer">MinerU 授權檔</a></li><li><a href="https://raw.githubusercontent.com/docling-project/docling/main/LICENSE" target="_blank" rel="noreferrer">Docling 授權檔</a></li><li><a href="https://raw.githubusercontent.com/qdrant/qdrant/master/LICENSE" target="_blank" rel="noreferrer">Qdrant 授權檔</a></li><li><a href="https://raw.githubusercontent.com/Arize-ai/phoenix/main/LICENSE" target="_blank" rel="noreferrer">Arize Phoenix 授權檔</a></li><li><a href="https://raw.githubusercontent.com/promptfoo/promptfoo/main/LICENSE" target="_blank" rel="noreferrer">promptfoo 授權檔</a></li><li><a href="https://raw.githubusercontent.com/langfuse/langfuse/main/LICENSE" target="_blank" rel="noreferrer">Langfuse 授權檔</a></li><li><a href="https://raw.githubusercontent.com/mostlygeek/llama-swap/main/LICENSE.md" target="_blank" rel="noreferrer">llama-swap 授權檔</a>, <a href="https://raw.githubusercontent.com/pgvector/pgvector/master/LICENSE" target="_blank" rel="noreferrer">pgvector 授權檔</a>, <a href="https://raw.githubusercontent.com/asg017/sqlite-vec/main/LICENSE-MIT" target="_blank" rel="noreferrer">sqlite-vec MIT 授權檔</a>, <a href="https://raw.githubusercontent.com/asg017/sqlite-vec/main/LICENSE-APACHE" target="_blank" rel="noreferrer">sqlite-vec Apache 2.0 授權檔</a></li></ul><p>模型授權 (官方授權頁與模型卡):</p><ul><li><a href="https://huggingface.co/nvidia/llama-nemotron-rerank-1b-v2" target="_blank" rel="noreferrer">Hugging Face 模型卡: nvidia/llama-nemotron-rerank-1b-v2</a></li><li><a href="https://huggingface.co/cross-encoder/mmarco-mMiniLMv2-L12-H384-v1/blob/265d6fb9678e8fc6b1adeda526533b2a1f1a7f07/README.md" target="_blank" rel="noreferrer">Hugging Face 模型卡: cross-encoder/mmarco-mMiniLMv2-L12-H384-v1</a></li><li><a href="https://dev.meta.ai/llama/llama4/license" target="_blank" rel="noreferrer">Llama 4 Community License Agreement</a>, <a href="https://huggingface.co/meta-llama/Llama-Guard-4-12B" target="_blank" rel="noreferrer">Llama Guard 4 模型卡</a>, <a href="https://huggingface.co/meta-llama/Llama-Prompt-Guard-2-86M" target="_blank" rel="noreferrer">Llama Prompt Guard 2 模型卡</a></li><li><a href="https://ai.google.dev/gemma/terms" target="_blank" rel="noreferrer">Gemma Terms of Use</a>, <a href="https://huggingface.co/google/embeddinggemma-300m" target="_blank" rel="noreferrer">EmbeddingGemma 模型卡</a></li><li><a href="https://huggingface.co/Snowflake/snowflake-arctic-embed-l-v2.0" target="_blank" rel="noreferrer">Snowflake Arctic Embed L v2.0 模型卡</a></li><li><a href="https://huggingface.co/taide/Gemma-3-TAIDE-12b-Chat-2602" target="_blank" rel="noreferrer">Gemma-3-TAIDE-12b-Chat-2602 模型卡</a></li></ul><p>所有權變動的來源見<a href="/lanai-handbook/ref/versions">版本頁</a>.</p><p>尚未查證: n8n 官方文件的 OSI 自述原句, LiteLLM 企業版功能範圍, MinerU 授權變更的版本界線, TAIDE 授權的商用條件.</p>',20)])])}const b=e(d,[["render",i]]);export{g as __pageData,b as default};
